import { Component, type ErrorInfo, type ReactNode } from "react";

interface Props {
  children: ReactNode;
  fallback?: (error: Error, reset: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  componentStack: string | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, componentStack: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo): void {
    console.error("[ErrorBoundary]", {
      message: error.message,
      stack: error.stack,
      componentStack: info.componentStack,
    });
    this.props.onError?.(error, info);
    this.setState({ componentStack: info.componentStack ?? null });
  }

  reset = (): void => {
    this.setState({ error: null, componentStack: null });
  };

  render(): ReactNode {
    const { error, componentStack } = this.state;

    if (error) {
      if (this.props.fallback) return this.props.fallback(error, this.reset);

      return (
        <div role="alert" style={{ padding: "1rem", border: "1px solid red", fontFamily: "monospace" }}>
          <h2 style={{ marginTop: 0 }}>Something went wrong</h2>
          <pre style={{ whiteSpace: "pre-wrap", color: "red", fontSize: "0.875rem" }}>
            {error.message}
          </pre>
          {componentStack && (
            <details>
              <summary style={{ cursor: "pointer", fontSize: "0.8rem" }}>Component stack</summary>
              <pre style={{ whiteSpace: "pre-wrap", fontSize: "0.75rem", opacity: 0.7 }}>
                {componentStack}
              </pre>
            </details>
          )}
          <button onClick={this.reset} style={{ marginTop: "0.5rem" }}>
            Try Again
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

